(* memory transfers for the replay-free [ref_exit_flush] below: through [mem_w1]'s stores,
   [__funcs_on_exit]'s [foe_post], and [mem_w2]'s stores *)
Ltac xw1 m1 H := subst m1; unfold mem_w1; repeat rdn_peel1; exact H.
Ltac xw2 POST m1 H := eapply (foe_post_rdn _ _ _ _ _ _ POST); [xw1 m1 H | zsimp; lia | zsimp; lia | zsimp; lia].
Ltac xw4 m4 POST m1 H := subst m4; unfold mem_w2; repeat rdn_peel1; xw2 POST m1 H.

Section VT2.
  Context {fx : FPState} {RL : Reloc} {RC : RelocCode RL} {RS : RelocSites RL} {RD : RelocData RL} {RW : RelocRW RL RD}.
Theorem exit_tail_flush :
  forall regs mem model (sp code : word) (wp2 rp2 : word)
         (wb wp : Z) (bufp bufsz rp1 can : word) (pending : list byte),
  getr regs 2 = Z_to_bv 64 (bv_unsigned sp - 16) -> getr regs 8 = code ->
  getr regs 1 = rl dF_15800 0x1586c ->
  (4294967296 <= bv_unsigned sp - 144)%Z -> (bv_unsigned sp <= 0x800000000000)%Z ->
  store_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp - 144)) 144%nat = true ->
  stdio_globals mem ->
  file_clean mem (0x1f440 + dA_1f440) wp2 rp2 ->
  stdout_pending mem wb wp bufp bufsz rp1 can pending ->
  m_halted model = None -> m_vm_lazy model = [] ->
  fd_lookup (m_fds model) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
  m_channel_reader model = true ->
  realizes RSEGS (mkCfg (mkst regs (rl dF_1771c 0x1771c) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof.
  rl_dwin_bounds.
  intros regs mem model sp code wp2 rp2 wb wp bufp bufsz rp1 can pending Hsp Hs0 Hra SPlo SPhi SOK G F2 SP Hh Hlazy Hfd Hrdr.
  destruct SP as [P1l P1wp P1wb P1wr P1buf P1bsz P1fd P1rp P1re RANGE LEN PMAX BYTES [Ggot Gcan]].
  rl_zaddr P1l; rl_zaddr P1wp; rl_zaddr P1wb; rl_zaddr P1wr; rl_zaddr P1buf; rl_zaddr P1bsz; rl_zaddr P1fd; rl_zaddr P1rp; rl_zaddr P1re.
  (* [comment removed for export] *)
  destruct G as (Gnl & Gofl & Gin & Gout & Gerr).
  destruct (w3b1 regs mem (seg_rom RSEGS) sp code wb wp)
    as (regs3 & RUN3 & R3a0 & R3a1 & R3a2 & R3ra & R3sp & R3s0 & R3gp & R3tp); try assumption; try lia.
  1:{ repeat split; [rl_zaddr Gnl|rl_zaddr Gofl|rl_zaddr Gin|rl_zaddr Gout|rl_zaddr Gerr]; rdn_solve. }
  1:{ repeat split; rl_zaddr_goal; rdn_solve. }
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN3 |]. clear RUN3.
  (* [comment removed for export] *)
  replace (rl dF_1771c 0x177cc) with (rl dF_1771c 0x177cc) in R3ra by (apply bv_eq; reflexivity).
  unfold W. rewrite <- (app_nil_r pending).
  set (mem3 := mem_w3a mem sp code).
  eapply (ref_stdio_write regs3 mem3 model (bv_unsigned sp - 32) (0x1f530 + dA_1f440) wb wp 1
            (Z_to_bv 64 0) (Z_to_bv 64 0) bufp bufsz can (rl dF_1771c 0x177cc) pending []);
    [ exact R3sp | exact R3a0 | exact R3a1 | exact R3a2 | exact R3ra
    | lia | lia
    | (* [comment removed for export] *)
      subst mem3; unfold mem_w3a; sok_stack SOK
    | lia | lia
    | (* [comment removed for export] *) split; subst mem3; unfold mem_w3a; rl_zaddr_goal; rdn_solve
    | (* [comment removed for export] *) split; subst mem3; unfold mem_w3a; rdn_solve
    | lia | exact Hfd | exact Hrdr | exact Hh | exact Hlazy
    | lia | lia | exact LEN
    | cbn [length]; u_norm; reflexivity
    | cbn [length]; lia
    | cbn [length]; lia
    | lia | u_norm; lia | u_norm; lia
    | subst mem3; unfold mem_w3a; repeat rdn_peel1; exact BYTES
    | reflexivity
    | rl_ret_ok
    | apply t_emit_has_nil
    | ].
  intros regs4 mem4 Q10 Q2 Q1 Q8 Q9 Q18 Q19 Q20 Q21 Q22 Q23 Q24 Q25 Q26 Q27 Q3 Q4 POST.
    rewrite R3s0 in Q8.
    destruct F2 as (F2l & F2wp & F2wb & F2rp & F2re).
    rl_zaddr F2l; rl_zaddr F2wp; rl_zaddr F2wb; rl_zaddr F2rp; rl_zaddr F2re.
    destruct (w3b2 regs4 mem4 (seg_rom RSEGS) sp code rp1 wp2 rp2) as (regs5 & RUN5 & R5a0 & R5a7 & R5sp); try assumption.
    all: try (eapply (sw_post_rdn _ _ _ _ _ _ _ _ _ POST); [subst mem3; unfold mem_w3a; rl_zaddr_goal; rdn_solve | zsimp; lia | zsimp; lia | zsimp; lia | zsimp; lia]).
    1:{ repeat split; (eapply (sw_post_rdn _ _ _ _ _ _ _ _ _ POST); [subst mem3; unfold mem_w3a; rl_zaddr_goal; rdn_solve | zsimp; lia | zsimp; lia | zsimp; lia | zsimp; lia]). }
    eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN5 |]. clear RUN5.
    eapply rz_exit_at; [exact F_1579c | exact E_1579c | exact Hh | exact Hlazy | left; exact R5a7 | exact R5a0].
Qed.
End VT2.

Section VP2.
  Context {fx : FPState} {RL : Reloc} {RC : RelocCode RL} {RS : RelocSites RL} {RD : RelocData RL} {RW : RelocRW RL RD}.
  Hypothesis FOE : funcs_on_exit_spec.
  Hypothesis CXF : cxa_finalize_ret.
Theorem ref_exit_flush :
  forall regs mem model (sp tp code : word) (tid : Z) (wp2 rp2 : word)
         (wb wp : Z) (bufp bufsz rp1 can : word) (pending : list byte),
  exit_common regs mem sp tp code tid wp2 rp2 ->
  stdout_pending mem wb wp bufp bufsz rp1 can pending ->
  m_halted model = None -> m_vm_lazy model = [] ->
  fd_lookup (m_fds model) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
  m_channel_reader model = true ->
  realizes RSEGS (mkCfg (mkst regs (rl dF_15800 0x15800) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof.
  rl_dwin_bounds.
  intros regs mem model sp tp code tid wp2 rp2 wb wp bufp bufsz rp1 can pending EC SP Hh Hlazy Hfd Hrdr.
  destruct EC as [Esp Etp Ea0 Esplo Esphi Esok Etplo Etphi Etid Emtid Elock Efe Efs Efa Ecomp Eg1 Eg2
                  [dso Edso] [v Eatexit] Eglob Eerr].
  (* __exit's prologue up to the call of __funcs_on_exit *)
  destruct (w1a regs mem (seg_rom RSEGS) sp tp code tid)
    as (regs1 & RUN1 & R1sp & R1s0 & R1ra & R1tp & R1gp & R1s1); try assumption.
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN1 |]. clear RUN1.
  set (m1 := mem_w1 mem sp (getr regs 1) (getr regs 8) tid) in *.
  assert (Gnl1 : rdn RSEGS m1 (rl dA_2f848 0x2f86b) 1%nat = Some [Z_to_bv 8 0]).
  { destruct Eglob as (Gnl & _). xw1 m1 Gnl. }
  assert (AT1 : atexit_state m1 v).
  { (* [A_IN_CALLBACK] unfolded to its [rl] address, so [rdn_peel1] can place it against the stores *)
    destruct v; unfold atexit_state in Eatexit |- *; try unfold A_IN_CALLBACK in *;
      repeat match goal with H : _ /\ _ |- _ => destruct H end;
      repeat split; match goal with H : rdn RSEGS mem ?a ?n = _ |- rdn RSEGS _ ?a ?n = _ => xw1 m1 H end. }
  (* __funcs_on_exit *)
  assert (SOK1 : store_ok RSEGS m1 (Z_to_bv 64 (bv_unsigned sp - 144)) 144%nat = true).
  { subst m1; unfold mem_w1; sok_stack Esok. }
  destruct (FOE regs1 m1 (seg_rom RSEGS) (bv_unsigned sp) v eq_refl R1sp R1ra ltac:(lia) ltac:(lia) SOK1 Gnl1 AT1)
    as (regs2 & m2 & RUN2 & R2sp & R2s0 & R2s1 & R2tp & R2gp & POST).
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN2 |]. clear RUN2.
  destruct (w1c regs2 m2 (seg_rom RSEGS)) as (regs3 & RUN3 & R3sp & R3s0 & R3ra & R3tp & R3gp & R3s1).
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN3 |]. clear RUN3.
  (* the facts after the callback walk: written by none of the three stack slots, the lock word
     or the atexit block *)
  assert (X2 : getr regs3 2 = Z_to_bv 64 (bv_unsigned sp - 16)) by (rewrite R3sp; exact R2sp).
  assert (X8 : getr regs3 8 = code) by (rewrite R3s0, R2s0; exact R1s0).
  assert (X9 : getr regs3 9 = getr regs 9) by (rewrite R3s1, R2s1; exact R1s1).
  assert (SOK2 : store_ok RSEGS m2 (Z_to_bv 64 (bv_unsigned sp - 144)) 144%nat = true).
  { eapply foe_post_store_ok; [exact POST|]. subst m1; unfold mem_w1; sok_stack Esok. }
  assert (M2fe : rdn RSEGS m2 (rl dA_1e3b8 0x1e3e8) 8%nat = Some (word_to_le_bytes 8 (rl dA_1e348 0x1e358))) by xw2 POST m1 Efe.
  assert (M2fs : rdn RSEGS m2 (rl dA_1e3b8 0x1e3f0) 8%nat = Some (word_to_le_bytes 8 (rl dA_1e348 0x1e350))) by xw2 POST m1 Efs.
  assert (M2fa : rdn RSEGS m2 (rl dA_1e348 0x1e350) 8%nat = Some (word_to_le_bytes 8 (rl dF_13140 0x13140))) by xw2 POST m1 Efa.
  assert (M2comp : rdn RSEGS m2 (rl dA_1f630 0x1f678) 1%nat = Some [Z_to_bv 8 0]) by xw2 POST m1 Ecomp.
  assert (M2g1 : rdn RSEGS m2 (rl dA_1e368 0x1e390) 8%nat = Some (word_to_le_bytes 8 (rl dE___cxa_finalize 0x13198))) by xw2 POST m1 Eg1.
  assert (M2g2 : rdn RSEGS m2 (rl dA_1e368 0x1e398) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0))) by xw2 POST m1 Eg2.
  assert (M2dso : rdn RSEGS m2 (rl dA_1f3f8 0x1f3f8) 8%nat = Some (word_to_le_bytes 8 dso)) by xw2 POST m1 Edso.
  (* __libc_exit_fini and the __cxa_finalize call, up to __stdio_exit *)
  destruct (w2 regs3 m2 (seg_rom RSEGS) sp code (getr regs 9) dso)
    as (regs4 & RUN4 & R4sp & R4s0 & R4ra & R4s1 & R4tp & R4gp); try assumption.
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN4 |]. clear RUN4.
  set (m4 := mem_w2 m2 sp code (getr regs 9)).
  destruct Eglob as (Gnl & Gofl & Gin & Gout & Gerr).
  destruct Eerr as (F2l & F2wp & F2wb & F2rp & F2re).
  destruct SP as [P1l P1wp P1wb P1wr P1buf P1bsz P1fd P1rp P1re RANGE LEN PMAX BYTES [Ggot Gcan]].
  (* the four memory premises are the bullets below; [try assumption] here compared them with every
     hypothesis up to conversion and never finished *)
  refine (exit_tail_flush regs4 m4 model sp code wp2 rp2 wb wp bufp bufsz rp1 can pending
           R4sp R4s0 R4ra Esplo Esphi _ _ _ _ Hh Hlazy Hfd Hrdr).
  - subst m4; unfold mem_w2; store_ok_peel; exact SOK2.
  - split; [xw4 m4 POST m1 Gnl|]. split; [xw4 m4 POST m1 Gofl|]. split; [xw4 m4 POST m1 Gin|]. split; [xw4 m4 POST m1 Gout|]. xw4 m4 POST m1 Gerr.
  - split; [xw4 m4 POST m1 F2l|]. split; [xw4 m4 POST m1 F2wp|]. split; [xw4 m4 POST m1 F2wb|]. split; [xw4 m4 POST m1 F2rp|]. xw4 m4 POST m1 F2re.
  - constructor; try assumption; try (xw4 m4 POST m1 P1l); try (xw4 m4 POST m1 P1wp); try (xw4 m4 POST m1 P1wb); try (xw4 m4 POST m1 P1wr); try (xw4 m4 POST m1 P1buf);
      try (xw4 m4 POST m1 P1bsz); try (xw4 m4 POST m1 P1fd); try (xw4 m4 POST m1 P1rp); try (xw4 m4 POST m1 P1re); try (xw4 m4 POST m1 BYTES).
    split; [xw4 m4 POST m1 Ggot | xw4 m4 POST m1 Gcan].
Qed.
End VP2.

