Section VP5.
  Context {fx : FPState} {RL : Reloc} {RC : RelocCode RL} {RS : RelocSites RL} {RD : RelocData RL} {RW : RelocRW RL RD}.
  Hypothesis FOE : funcs_on_exit_spec.
  Hypothesis CXF : cxa_finalize_ret.
Corollary ref_exit_Z : forall regs mem model code pending,
  exit_pre regs mem model code pending ->
  realizes RSEGS (mkCfg (mkst regs (rl dF_15800 0x15800) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof. intros regs mem model code pending PRE. eapply ref_exit; eassumption. Qed.
End VP5.

